  ],
  "key_assumptions": [
    {
      "assumption": "AI companies prioritize shareholder value over social stability.",
      "if_wrong": "If firms are altruistic, strict liability becomes an unnecessary and punitive tax on innovation."
    },
    {
      "assumption": "Current market incentives are incapable of self-correcting for negative externalities.",
